171:int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
172:    // Only data as a mem file purely for purposes of determining format
173:    hFILE *memfile;
174:    uint8_t *copy = malloc(size);
175:    if (copy == NULL) {
176:        abort();
177:    }
178:    memcpy(copy, data, size);
179:    // hopen does not take ownership of `copy`, but hts_hopen does.
180:    memfile = hopen("mem:", "rb:", copy, size);
181:    if (memfile == NULL) {
182:        free(copy);
183:        return 0;
184:    }
185:
186:    htsFile *ht_file = hts_hopen(memfile, "data", "rb");
187:    if (ht_file == NULL) {
188:        if (hclose(memfile) != 0) {
189:            abort();
190:        }
191:        return 0;
192:    }
193:    int ftype = ht_file->format.category;
194:    hts_close(ht_file);
195:
196:    // Now repeat a read-write loop multiple times per input, testing
197:    // encoding in all output formats.
198:    // (Although we could just ignore ftype and do all 5 for all inputs)
199:    switch (ftype) {
200:        case sequence_data:
201:            view_sam(data, size, "w",  1); // SAM
202:            view_sam(data, size, "wb", 1); // BAM
203:            view_sam(data, size, "wc", 0); // CRAM
204:            break;
205:        case variant_data:
206:            view_vcf(data, size, "w");     // VCF
207:            view_vcf(data, size, "wb");    // BCF
208:            break;
209:        default:
210:            break;
211:    }
212:    return 0;
213:}
